function translateMeasured(value,bn){
 const key=value.trim();let m;
 if(!bn){
  if(m=key.match(/^([+\d.,]+) শতক \/ ([\d.,]+) একর$/))return m[1]+' decimals / '+m[2]+' acres';
  if(m=key.match(/^\(([\d.,]+) শতক\)$/))return '('+m[1]+' decimals)';
  if(m=key.match(/^([+\d.,]+)% পৃষ্ঠতল বৃদ্ধি \(([+\d.,]+) শতক\)$/))return m[1]+'% surface difference ('+m[2]+' decimals)';
  if(m=key.match(/^(?:গড় ঢাল:|Mean slope:) ([\d.,]+)° \(সর্বোচ্চ: ([\d.,]+)°\)$/))return 'Mean slope: '+m[1]+'° (maximum: '+m[2]+'°)';
 }else{
  if(m=key.match(/^(Mouza|Khatian|Area|Source): (.*)$/))return ({Mouza:'মৌজা',Khatian:'খতিয়ান',Area:'আয়তন',Source:'উৎস'})[m[1]]+': '+(m[2]==='DEMO'?'নমুনা':m[2].replace(/ decimal$/,' শতক'));
  if(m=key.match(/^Mean slope: ([\d.,]+)° \(সর্বোচ্চ: ([\d.,]+)°\)$/))return 'গড় ঢাল: '+m[1]+'° (সর্বোচ্চ: '+m[2]+'°)';
 }
 return null;
}
